<script lang="ts">
	import { CallControls, CallGrid, type CallParticipant, type CallQualityOption } from '../call';
	import { ChatPanel, ChatUnreadBadge, type ChatMessage } from '../chat';
	let { roomId, inviteUrl, status, participants, local, chatOpen = $bindable(false), unread = 0, messages = [], microphoneMuted, videoState, quality, qualityOptions, error = '', onCopyInvite, onSendChat, onToggleMicrophone, onToggleCamera, onToggleScreen, onQualityChange, onLeave }: {
		roomId: string; inviteUrl: string; status: string; participants: readonly CallParticipant[]; local: CallParticipant; chatOpen?: boolean; unread?: number; messages?: readonly ChatMessage[]; microphoneMuted: boolean; videoState: 'camera' | 'screen' | 'off'; quality: string; qualityOptions: readonly CallQualityOption[]; error?: string; onCopyInvite: () => void; onSendChat: (text: string) => void; onToggleMicrophone: () => void; onToggleCamera: () => void; onToggleScreen: () => void; onQualityChange: (quality: string) => void; onLeave: () => void;
	} = $props();
</script>

<main class="room-shell">
	<aside class="app-sidebar" aria-label="Application navigation">
		<div class="brand"><strong>PeerCast</strong><span>CLIENT</span></div>
		<div class="sidebar-content">
			<div><p class="side-label">Connection</p><div class="connection"><span class="status">● {status}</span><span class="room-id">ROOM / {roomId}</span></div></div>
			<div><p class="side-label">Participants ({participants.length + 1})</p><ul><li><i class="local-dot"></i><span>{local.displayName} (you)</span>{#if local.isHost}<em>Host</em>{/if}</li>{#each participants as participant (participant.id)}<li><i></i><span>{participant.displayName}</span>{#if participant.isHost}<em>Host</em>{/if}</li>{/each}</ul></div>
			<div><p class="side-label">Invite link</p><label><input readonly value={inviteUrl} aria-label="Invite link" onclick={(event) => event.currentTarget.select()} /><button type="button" onclick={onCopyInvite} aria-label="Copy invite link">Copy</button></label></div>
			<div class="devices"><p class="side-label">Devices</p><CallControls {microphoneMuted} {videoState} {quality} {qualityOptions} onToggleMicrophone={onToggleMicrophone} onToggleCamera={onToggleCamera} onToggleScreen={onToggleScreen} onQualityChange={onQualityChange} onLeave={onLeave} /></div>
		</div>
		<div class="side-user"><i>{local.displayName.slice(0, 1).toUpperCase() || '?'}</i><div><b>{local.displayName}</b><small>{local.isHost ? 'Host' : 'Participant'}</small></div></div>
	</aside>
	<div class="room-main"><header class="app-header"><h2>Room</h2><span class="header-room">{roomId}</span><div class="header-actions"><button type="button" class="chat-toggle" onclick={() => chatOpen = !chatOpen}>Chat <ChatUnreadBadge count={unread} /></button><button type="button" class="leave" onclick={onLeave}>Leave</button></div></header><section class="stage"><CallGrid {local} {participants} />{#if error}<p class="error" role="alert">{error}</p>{/if}</section></div>
	<ChatPanel open={chatOpen} {messages} connected={status === 'connected'} onOpenChange={(open) => chatOpen = open} onSend={onSendChat} />
</main>

