	@media (min-width:768px) { .room-shell:has(:global(.chat-panel)) { grid-template-columns:18rem minmax(0,1fr) 20rem; }.room-shell :global(.chat-panel) { margin:.75rem .75rem .75rem 0; } }
	@media (max-width:1023px) { .room-shell { height:auto; min-height:100dvh; grid-template-columns:minmax(0,1fr); overflow:visible; }.app-sidebar { order:2; border-top:1px solid #1e293b; border-right:0; }.sidebar-content { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); overflow:visible; }.devices { margin-top:0; }.side-user { display:none; }.room-main { min-height:75dvh; }.stage { overflow:auto; } }
	@media (max-width:767px) { .app-header { padding:0 .65rem; }.header-room { display:none; }.header-actions button { min-height:2.25rem; }.sidebar-content { grid-template-columns:1fr; }.app-sidebar { padding-bottom:env(safe-area-inset-bottom); }.stage { padding:.5rem; } }
